import os

import boto3


def get_observability_client():
    region = os.getenv('AWS_REGION', 'us-west-2')
    return boto3.client('cloudwatch', region_name=region)


def get_config():
    return {
        'region': os.getenv('AWS_REGION', 'us-west-2'),
        'namespace': os.getenv('METRICS_NAMESPACE', 'MyAppMetrics'),
        'dimensions': {
            'Environment': os.getenv('ENVIRONMENT', 'prod')
        }
    }

from typing import Any, Dict, List


def normalize_metric_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'metric': payload['metric'],
        'start_time': int(payload['start_time']),
        'end_time': int(payload['end_time']),
        'dimensions': {k: v for k, v in payload['dimensions'].items()}
    }


def normalize_metric_response(response: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [{'timestamp': p['Timestamp'].timestamp(), 'value': float(p['Average'])} for p in response['Datapoints']]

import re


def metric_annotation_safety(payload):
    annotation = payload['annotation']
    if re.search(r'[a-zA-Z0-9]{4,}', annotation):
        return {'safe': True}
    return {'safe': False}

import boto3


def dashboard_note_translate(payload, config=None):
    config = config or {}
    client = boto3.client('translate', region_name=config.get('region'))
    response = client.translate_text(Text=payload['note'], SourceLanguageCode='en', TargetLanguageCode=payload['target_language'])
    return {'translated_note': response['TranslatedText']}

import boto3


def metrics_export_archive(payload, config=None):
    config = config or {}
    client = boto3.client('s3', region_name=config.get('region'))
    client.put_object(Bucket=config['bucket'], Key=payload['key'], Body=payload['data'])
    return {'status': 'success'}
